package village.vale.client;
public final class DodgeServerCapabilityChecks {static int n;static void check(boolean b){n++;if(!b)throw new AssertionError("check "+n);}public static void main(String[] args){DodgeServerCapability c=new DodgeServerCapability();Object a=new Object(),b=new Object();check(!c.supports(a,"0.3.16",true));c.registration(a,true,"REGISTER",true);check(c.supports(a,"0.3.16",true));check(c.supports(a,"0.3.14",true));check(!c.supports(a,"0.3.13",true));check(!c.supports(a,"0.4.0",true));check(!c.supports(a,"garbage",true));check(c.supports(a,null,true));check(!c.supports(b,"0.3.16",true));check(!c.supports(null,"0.3.16",true));check(!c.supports(a,"0.3.16",false));c.registration(b,false,"REGISTER",true);check(!c.supports(b,null,true));c.registration(b,true,"REGISTER",false);check(!c.supports(b,null,true));c.registration(b,true,"REGISTER",true);check(c.supports(b,null,true)&&c.supports(a,null,true));c.disconnect(a);check(!c.supports(a,null,true)&&c.supports(b,null,true));c.registration(a,true,"REGISTER",true);c.registration(a,true,"UNREGISTER",true);check(!c.supports(a,null,true)&&c.supports(b,null,true));c.registration(b,true,"nonsense",true);check(c.supports(b,null,true));c.disconnect(b);check(!c.supports(b,null,true));Object[] holders=new Object[5];for(int i=0;i<5;i++){holders[i]=new Object();c.registration(holders[i],true,"REGISTER",true);}check(c.size()==4&&!c.supports(holders[0],null,true)&&c.supports(holders[4],null,true));System.out.println("DODGE_SERVER_CAPABILITY_PASS: "+n);}}
